def transform(grid):
    n = len(grid)
    sep = next((r for r in range(n) if all(v == grid[r][0] for v in grid[r]) and grid[r][0] != 0), None)
    if sep is None:
        return grid
    divider = grid[sep][0]
    row_divs = [r for r in range(n) if all(v == divider for v in grid[r])]
    col_divs = [c for c in range(len(grid[0])) if all(grid[r][c] == divider for r in range(n))]
    row_starts = [0] + [r + 1 for r in row_divs]
    col_starts = [0] + [c + 1 for c in col_divs]
    h, w = row_divs[0], col_divs[0]

    # The non-square object supplies the pattern to copy.
    pattern = None
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r0+h) for c in range(c0, c0+w)
                     if grid[r][c] not in (0, divider)]
            if cells and len(cells) != 4:
                color = cells[0][2]
                pattern = {(r, c) for r, c, v in cells if v == color}
                break
        if pattern:
            break

    out = [[divider if r in row_divs or c in col_divs else 0
            for c in range(len(grid[0]))] for r in range(n)]
    if not pattern:
        return grid

    for r0 in row_starts:
        # Determine the row's color from its first panel.
        color = next((grid[r][c] for r in range(r0, r0+h)
                      for c in range(w) if grid[r][c] not in (0, divider)), 0)
        for c0 in col_starts:
            for dr, dc in pattern:
                out[r0+dr][c0+dc] = color
    return out
